ALTER TABLE public.fleet_movements ADD COLUMN IF NOT EXISTS fuel_consumed numeric NOT NULL DEFAULT 0; ALTER TABLE public.fleet_movements ADD CONSTRAINT fleet_movements_fuel_consumed_chk CHECK (fuel_consumed >= 0); CREATE OR REPLACE FUNCTION public.calculate_fleet_fuel(p_origin_planet_id uuid, p_destination_planet_id uuid, p_ship_id text, p_quantity bigint) RETURNS numeric LANGUAGE plpgsql STABLE SET search_path TO 'public','pg_temp' AS $function$ DECLARE v_distance numeric; v_speed numeric; v_consumption numeric; BEGIN IF p_quantity <= 0 THEN RAISE EXCEPTION 'Quantity must be greater than 0'; END IF; SELECT sd.speed,sd.fuel_consumption INTO v_speed,v_consumption FROM public.ship_definitions sd WHERE sd.id=p_ship_id; IF NOT FOUND THEN RAISE EXCEPTION 'Unknown ship: %',p_ship_id; END IF; IF v_consumption <= 0 THEN RETURN 0; END IF; IF p_destination_planet_id IS NULL THEN RAISE EXCEPTION 'Destination planet is required'; END IF; v_distance:=public.calculate_fleet_distance(p_origin_planet_id,p_destination_planet_id); RETURN ceil(v_consumption*p_quantity*(v_distance/35000.0)*power((v_speed/10.0)+1,2)); END; $function$; CREATE OR REPLACE FUNCTION public.calculate_fleet_fuel_mixed(p_origin_planet_id uuid,p_destination_planet_id uuid,p_ships jsonb) RETURNS numeric LANGUAGE plpgsql STABLE SET search_path TO 'public','pg_temp' AS $function$ DECLARE r record; v_total numeric:=0; BEGIN IF p_ships IS NULL OR jsonb_typeof(p_ships)<>'object' OR p_ships='{}'::jsonb THEN RAISE EXCEPTION 'Fleet composition must be a non-empty JSON object'; END IF; FOR r IN SELECT key AS ship_id,value::bigint AS quantity FROM jsonb_each_text(p_ships) ORDER BY key LOOP v_total:=v_total+public.calculate_fleet_fuel(p_origin_planet_id,p_destination_planet_id,r.ship_id,r.quantity); END LOOP; RETURN v_total; END; $function$;